// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address owner = address(0xabc);
        vm.deal(owner, amount);
        vm.prank(owner);
        c = new SimpleWallet();
        vm.deal(address(c), amount);
        require(c.owner() == owner, "owner mismatch");

        bool ok;
        vm.prank(owner);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok ? address(c).balance == 0 : true);
    }
}
